INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('js-async-await', 'JavaScript async/await 完全指南', '2025-04-10', 'JavaScript', '深入理解异步编程，从 Promise 到 async/await 的演进之路。', '## 前言\n\n异步编程是 JavaScript 的核心概念之一。本文将从 Promise 讲起，逐步深入 async/await。\n\n## Promise 基础\n\nPromise 是异步操作的容器，代表一个最终会完成（或失败）的操作。\n\n```javascript\nconst fetchUser = new Promise((resolve, reject) => {\n  setTimeout(() => {\n    resolve({ name: \"星辰\", age: 25 })\n  }, 1000)\n})\n\nfetchUser.then(user => console.log(user))\n```\n\n## async/await 语法糖\n\nasync/await 让异步代码看起来像同步代码，大大提升了可读性。\n\n```javascript\nasync function getUser() {\n  try {\n    const response = await fetch(\"/api/user\")\n    const user = await response.json()\n    console.log(user)\n  } catch (error) {\n    console.error(\"获取用户失败:\", error)\n  }\n}\n```\n\n## 并发控制\n\n当需要同时发起多个请求时，使用 Promise.all 而不是逐个 await。\n\n```javascript\nconst [users, posts, comments] = await Promise.all([\n  fetchUsers(),\n  fetchPosts(),\n  fetchComments()\n])\n```\n\n## 常见陷阱\n\n1. 忘记处理错误：始终使用 try/catch 或 .catch()\n2. 在循环中误用 await：forEach 不会等待 async 函数\n3. 不必要的串行化：独立的异步操作应该并发执行\n\n## 总结\n\n- async/await 是 Promise 的语法糖，让代码更易读\n- 独立的异步操作用 Promise.all 并发执行\n- 始终做好错误处理');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('typescript-generics', 'TypeScript 泛型入门到精通', '2025-03-28', 'TypeScript', '系统讲解 TypeScript 泛型的使用场景和高级技巧。', '## 什么是泛型\n\n泛型允许我们编写可复用的、类型安全的代码，而不必预先指定具体类型。\n\n## 基础用法\n\n```typescript\nfunction identity<T>(arg: T): T {\n  return arg\n}\n\nconst num = identity(42)\nconst str = identity(\"hello\")\n```\n\n## 泛型约束\n\n使用 extends 关键字约束泛型的范围。\n\n```typescript\ninterface HasLength {\n  length: number\n}\n\nfunction logLength<T extends HasLength>(arg: T): T {\n  console.log(arg.length)\n  return arg\n}\n\nlogLength(\"hello\")\nlogLength([1, 2, 3])\n```\n\n## 泛型工具类型\n\nTypeScript 内置了许多实用的泛型工具类型。\n\n```typescript\ntype User = { name: string; age: number }\ntype PartialUser = Partial<User>\ntype UserPreview = Pick<User, \"name\">\ntype UserWithoutAge = Omit<User, \"age\">\n```\n\n## 实际应用：API 响应封装\n\n```typescript\ninterface ApiResponse<T> {\n  code: number\n  message: string\n  data: T\n}\n\nasync function fetchApi<T>(url: string): Promise<ApiResponse<T>> {\n  const res = await fetch(url)\n  return res.json()\n}\n```\n\n## 总结\n\n- 泛型是 TypeScript 类型系统的核心特性\n- 善用泛型约束保证类型安全\n- 内置工具类型能减少大量重复代码');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('css-grid-layout', 'CSS Grid 布局实战手册', '2025-04-05', 'CSS', '通过实际案例掌握 CSS Grid 二维布局的核心概念和常用技巧。', '## 为什么用 Grid\n\nGrid 是 CSS 中唯一的二维布局系统，能同时控制行和列。\n\n## 基本网格\n\n```css\n.container {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 20px;\n}\n```\n\n## 响应式网格\n\n使用 minmax() 和 auto-fit 实现纯 CSS 响应式布局。\n\n```css\n.container {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n  gap: 16px;\n}\n```\n\n这个技巧不需要媒体查询，卡片会自动根据容器宽度换行。\n\n## 网格区域命名\n\n对于复杂布局，命名区域更直观。\n\n```css\n.layout {\n  display: grid;\n  grid-template-areas:\n    \"header header header\"\n    \"sidebar main main\"\n    \"footer footer footer\";\n  grid-template-columns: 200px 1fr 1fr;\n}\n\n.header  { grid-area: header; }\n.sidebar { grid-area: sidebar; }\n.main    { grid-area: main; }\n.footer  { grid-area: footer; }\n```\n\n## Grid vs Flexbox\n\n- 一维布局（行或列）用 Flexbox\n- 二维布局（行和列）用 Grid\n- 实际开发中两者经常配合使用\n\n## 总结\n\n- Grid 擅长整体页面布局\n- auto-fit + minmax() 实现优雅的响应式\n- 命名区域让复杂布局更易维护');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('git-workflow', 'Git 分支管理最佳实践', '2025-03-10', '工具', '团队协作中的 Git 分支策略和常用工作流。', '## 为什么需要分支策略\n\n没有规范的分支管理，团队协作会变成噩梦。\n\n## Git Flow\n\n经典的分支模型，适合发版节奏明确的项目。\n\n- main：生产环境代码\n- develop：开发主干\n- feature/*：功能分支\n- hotfix/*：紧急修复\n\n## GitHub Flow\n\n更简洁的工作流，适合持续部署的项目。\n\n1. 从 main 创建分支\n2. 开发完成后提交 PR\n3. Code Review 通过后合并\n4. 自动部署\n\n## 常用命令\n\n```bash\n# 创建并切换分支\ngit checkout -b feature/user-auth\n\n# 合并分支\ngit merge feature/user-auth\n\n# 变基（保持线性历史）\ngit rebase main\n\n# 暂存当前工作\ngit stash\ngit stash pop\n```\n\n## Commit 规范\n\n```\nfeat: 新功能\nfix: 修复 bug\ndocs: 文档更新\nstyle: 代码格式\nrefactor: 重构\ntest: 测试\nchore: 构建/工具\n```\n\n## 总结\n\n- 小团队用 GitHub Flow 足够\n- 大项目考虑 Git Flow\n- Commit message 遵循约定式提交');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('docker-basics', 'Docker 入门：从零开始容器化你的应用', '2025-04-15', 'DevOps', '学习 Docker 核心概念，掌握容器化应用的基本操作。', '## 什么是 Docker\n\nDocker 让你把应用和它的依赖打包成一个轻量级的容器，在任何环境中都能一致运行。\n\n## 核心概念\n\n- 镜像（Image）：应用的只读模板\n- 容器（Container）：镜像的运行实例\n- Dockerfile：构建镜像的指令文件\n\n## 编写 Dockerfile\n\n```dockerfile\nFROM node:20-alpine\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci --production\nCOPY . .\nEXPOSE 3000\nCMD [\"node\", \"index.js\"]\n```\n\n## 常用命令\n\n```bash\n# 构建镜像\ndocker build -t my-app .\n\n# 运行容器\ndocker run -d -p 3000:3000 my-app\n\n# 查看运行中的容器\ndocker ps\n\n# 查看日志\ndocker logs <container-id>\n\n# 停止容器\ndocker stop <container-id>\n```\n\n## Docker Compose\n\n管理多个容器的编排工具。\n\n```yaml\nversion: \"3\"\nservices:\n  app:\n    build: .\n    ports:\n      - \"3000:3000\"\n    depends_on:\n      - db\n  db:\n    image: mysql:8\n    environment:\n      MYSQL_ROOT_PASSWORD: password\n      MYSQL_DATABASE: myapp\n```\n\n## 总结\n\n- Docker 解决了 \"在我电脑上能跑\" 的问题\n- Dockerfile 定义如何构建镜像\n- Docker Compose 管理多容器应用');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('react-hooks-guide', 'React Hooks 深度解析', '2025-02-15', 'React', '全面理解 React Hooks 的工作原理和使用模式。', '## 为什么引入 Hooks\n\nHooks 解决了 class 组件的三个问题：逻辑复用难、复杂组件难理解、this 指向困惑。\n\n## useState\n\n管理组件内部状态。\n\n```jsx\nfunction Counter() {\n  const [count, setCount] = useState(0)\n  return (\n    <button onClick={() => setCount(count + 1)}>\n      点击了 {count} 次\n    </button>\n  )\n}\n```\n\n## useEffect\n\n处理副作用：数据请求、订阅、DOM 操作。\n\n```jsx\nfunction UserProfile({ userId }) {\n  const [user, setUser] = useState(null)\n\n  useEffect(() => {\n    fetchUser(userId).then(setUser)\n  }, [userId])\n\n  if (!user) return <div>加载中...</div>\n  return <div>{user.name}</div>\n}\n```\n\n## 自定义 Hook\n\n将组件逻辑提取为可复用的函数。\n\n```jsx\nfunction useFetch(url) {\n  const [data, setData] = useState(null)\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    setLoading(true)\n    fetch(url)\n      .then(res => res.json())\n      .then(data => {\n        setData(data)\n        setLoading(false)\n      })\n  }, [url])\n\n  return { data, loading }\n}\n```\n\n## Hooks 规则\n\n1. 只在组件顶层调用，不要在循环/条件中使用\n2. 只在 React 函数组件或自定义 Hook 中调用\n\n## 总结\n\n- useState 管理状态，useEffect 处理副作用\n- 自定义 Hook 是逻辑复用的最佳方式\n- 遵守 Hooks 规则，避免奇怪的 bug');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('js-performance', 'JavaScript 性能优化实战', '2025-04-20', '性能优化', '前端性能优化的实用技巧，从加载到运行时全面提速。', '## 性能优化的意义\n\n页面加载每慢 1 秒，用户流失 7%。性能就是用户体验。\n\n## 加载优化\n\n### 代码分割\n\n```javascript\nconst Home = () => import(\"./views/Home.vue\")\nconst About = () => import(\"./views/About.vue\")\n```\n\n### 资源压缩\n\n- 开启 Gzip/Brotli 压缩\n- 图片使用 WebP 格式\n- CSS/JS 去除无用代码（Tree Shaking）\n\n## 渲染优化\n\n### 防抖与节流\n\n```javascript\n// 防抖：输入搜索\nfunction debounce(fn, delay) {\n  let timer\n  return (...args) => {\n    clearTimeout(timer)\n    timer = setTimeout(() => fn(...args), delay)\n  }\n}\n\n// 节流：滚动监听\nfunction throttle(fn, interval) {\n  let last = 0\n  return (...args) => {\n    const now = Date.now()\n    if (now - last >= interval) {\n      last = now\n      fn(...args)\n    }\n  }\n}\n```\n\n## 运行时优化\n\n- 使用 requestAnimationFrame 做动画\n- 避免强制同步布局（读写分离）\n- 使用 Web Worker 处理密集计算\n\n## 总结\n\n- 先测量再优化，用 Lighthouse 找瓶颈\n- 加载优化：懒加载 + 压缩\n- 渲染优化：虚拟列表 + 防抖节流');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('mysql-index', 'MySQL 索引优化指南', '2025-03-05', '数据库', '理解 MySQL 索引原理，掌握慢查询优化的实用技巧。', '## 为什么需要索引\n\n没有索引的表就像没有目录的字典，每次查询都要全表扫描。\n\n## 索引类型\n\n### B+ 树索引（默认）\n\n```sql\nCREATE INDEX idx_user_email ON users(email);\nCREATE INDEX idx_status_date ON orders(status, created_at);\n```\n\n### 前缀索引\n\n对于长字符串，只索引前几个字符。\n\n```sql\nCREATE INDEX idx_name_prefix ON users(name(10));\n```\n\n## EXPLAIN 分析\n\n```sql\nEXPLAIN SELECT * FROM orders WHERE status = \"paid\" AND created_at > \"2025-01-01\";\n```\n\n关注这些字段：\n- type：ALL（全表扫描）到 const，越往右越好\n- rows：扫描行数，越少越好\n- Extra：Using index（覆盖索引）是好事\n\n## 最左前缀原则\n\n复合索引 (a, b, c) 可以匹配：\n- WHERE a = 1\n- WHERE a = 1 AND b = 2\n- WHERE a = 1 AND b = 2 AND c = 3\n\n不能匹配：\n- WHERE b = 2\n- WHERE c = 3\n\n## 常见优化场景\n\n```sql\n-- 避免 SELECT *\nSELECT id, name, email FROM users WHERE id = 1\n\n-- 避免在索引列上函数运算\n-- 不好\nSELECT * FROM orders WHERE YEAR(created_at) = 2025\n-- 好\nSELECT * FROM orders WHERE created_at >= \"2025-01-01\" AND created_at < \"2026-01-01\"\n\n-- 分页优化\n-- 慢\nSELECT * FROM orders LIMIT 100000, 20\n-- 快\nSELECT * FROM orders WHERE id > 100000 LIMIT 20\n```\n\n## 总结\n\n- 索引是空间换时间的典型方案\n- 用 EXPLAIN 分析查询计划\n- 遵循最左前缀原则设计复合索引');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('vue-router-guide', 'Vue Router 进阶技巧', '2025-04-01', 'Vue', '深入 Vue Router 的高级用法，包括导航守卫、路由元信息和动态路由。', '## 导航守卫\n\n控制路由跳转的权限和逻辑。\n\n```javascript\nrouter.beforeEach((to, from, next) => {\n  const isLoggedIn = localStorage.getItem(\"token\")\n  if (to.meta.requiresAuth && !isLoggedIn) {\n    next(\"/login\")\n  } else {\n    next()\n  }\n})\n```\n\n## 路由元信息\n\n给路由附加自定义数据。\n\n```javascript\nconst routes = [\n  {\n    path: \"/admin\",\n    component: AdminLayout,\n    meta: { requiresAuth: true, role: \"admin\" }\n  },\n  {\n    path: \"/login\",\n    component: LoginPage,\n    meta: { guestOnly: true }\n  }\n]\n```\n\n## 动态路由\n\n根据用户权限动态添加路由。\n\n```javascript\nrouter.addRoute({\n  path: \"/dashboard\",\n  component: Dashboard,\n  name: \"Dashboard\"\n})\n```\n\n## 路由懒加载\n\n```javascript\nconst routes = [\n  {\n    path: \"/\",\n    component: () => import(\"../views/HomePage.vue\")\n  },\n  {\n    path: \"/blog/:id\",\n    component: () => import(\"../views/BlogDetail.vue\")\n  }\n]\n```\n\n## 滚动行为\n\n```javascript\nconst router = createRouter({\n  history: createWebHistory(),\n  routes,\n  scrollBehavior(to, from, savedPosition) {\n    if (savedPosition) return savedPosition\n    if (to.hash) return { el: to.hash, behavior: \"smooth\" }\n    return { top: 0 }\n  }\n})\n```\n\n## 总结\n\n- 导航守卫处理权限控制\n- 路由元信息存储页面配置\n- 动态路由实现按需加载');
INSERT INTO blogs (id, title, date, category, summary, content) VALUES
('node-express-rest', 'Node.js + Express 构建 REST API', '2025-03-20', 'Node.js', '从零搭建一个规范的 Express REST API 服务。', '## 项目结构\n\n```\nserver/\n├── routes/\n│   ├── users.js\n│   └── posts.js\n├── middleware/\n│   ├── auth.js\n│   └── errorHandler.js\n├── db.js\n└── index.js\n```\n\n## 基础路由\n\n```javascript\nconst express = require(\"express\")\nconst router = express.Router()\n\nrouter.get(\"/\", async (req, res) => {\n  const [rows] = await pool.query(\"SELECT * FROM users\")\n  res.json(rows)\n})\n\nrouter.post(\"/\", async (req, res) => {\n  const { name, email } = req.body\n  const [result] = await pool.query(\n    \"INSERT INTO users (name, email) VALUES (?, ?)\",\n    [name, email]\n  )\n  res.status(201).json({ id: result.insertId })\n})\n```\n\n## 错误处理中间件\n\n```javascript\nfunction errorHandler(err, req, res, next) {\n  console.error(err.stack)\n  res.status(err.status || 500).json({\n    error: err.message || \"服务器内部错误\"\n  })\n}\n\napp.use(errorHandler)\n```\n\n## 请求验证\n\n```javascript\nfunction validateUser(req, res, next) {\n  const { name, email } = req.body\n  if (!name || !email) {\n    return res.status(400).json({ error: \"名称和邮箱必填\" })\n  }\n  next()\n}\n\nrouter.post(\"/\", validateUser, async (req, res) => {\n  // 处理逻辑\n})\n```\n\n## 统一响应格式\n\n```javascript\nfunction success(data, message = \"操作成功\") {\n  return { code: 0, message, data }\n}\n\nfunction fail(message = \"操作失败\", code = 1) {\n  return { code, message }\n}\n\nres.json(success(users, \"获取用户列表成功\"))\nres.status(404).json(fail(\"用户不存在\"))\n```\n\n## 总结\n\n- 路由模块化，按资源拆分\n- 统一错误处理和响应格式\n- 中间件处理通用逻辑（验证、鉴权）');
